<?php
require_once __DIR__ . '/../includes/db.php';
require_once __DIR__ . '/../includes/auth.php';
require_super_admin();
$pdo=db();
$activities=$pdo->query('SELECT l.*,a.name admin_name FROM activity_logs l LEFT JOIN admins a ON a.id=l.admin_id ORDER BY l.created_at DESC LIMIT 100')->fetchAll();
$resultAudits=$pdo->query('SELECT r.*,e.name event_name,s.name sport_name,a.name admin_name FROM result_audits r JOIN events e ON e.id=r.event_id JOIN sports s ON s.id=e.sport_id LEFT JOIN admins a ON a.id=r.admin_id ORDER BY r.created_at DESC LIMIT 100')->fetchAll();
require_once __DIR__ . '/../includes/layout.php';page_head('Audit Log');
?>
<div class="admin-hero"><div><span class="eyebrow">Meet Administrator only</span><h1>Audit Log</h1><p class="admin-subtitle">A chronological record of administrator actions and verified result changes.</p></div></div>
<?php admin_nav('audit'); ?>
<section class="audit-section"><div class="directory-heading"><div><span class="form-kicker">Account and schedule activity</span><h2>Administration activity</h2></div><p>Most recent 100 actions.</p></div><div class="table-card audit-table"><table class="score-table"><thead><tr><th>When</th><th>Administrator</th><th>Action</th><th>Details</th></tr></thead><tbody><?php if(!$activities): ?><tr><td class="empty" colspan="4">No activity has been recorded yet.</td></tr><?php endif; ?><?php foreach($activities as $activity): ?><tr><td><?= date('M j, Y · g:i A',strtotime($activity['created_at'])) ?></td><td><?= htmlspecialchars($activity['admin_name'] ?: 'Deleted administrator') ?></td><td><span class="audit-action"><?= htmlspecialchars(ucwords(str_replace('_',' ',$activity['action']))) ?></span></td><td><?= htmlspecialchars($activity['description']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="audit-section"><div class="directory-heading"><div><span class="form-kicker">Published medal results</span><h2>Result history</h2></div><p>Every publish and correction is retained.</p></div><div class="table-card audit-table"><table class="score-table"><thead><tr><th>When</th><th>Administrator</th><th>Event</th><th>Change</th></tr></thead><tbody><?php if(!$resultAudits): ?><tr><td class="empty" colspan="4">No result history has been recorded yet.</td></tr><?php endif; ?><?php foreach($resultAudits as $audit): $before=json_decode($audit['previous_result'] ?? '',true) ?: []; $after=json_decode($audit['new_result'],true) ?: []; ?><tr><td><?= date('M j, Y · g:i A',strtotime($audit['created_at'])) ?></td><td><?= htmlspecialchars($audit['admin_name'] ?: 'Deleted administrator') ?></td><td><strong><?= htmlspecialchars($audit['event_name']) ?></strong><br><small><?= htmlspecialchars($audit['sport_name']) ?></small></td><td><span class="audit-action"><?= htmlspecialchars(ucfirst($audit['action'])) ?></span><?php if($before): ?><small class="audit-before">Before: G <?= htmlspecialchars($before['gold_team'] ?? '—') ?> · S <?= htmlspecialchars($before['silver_team'] ?? '—') ?> · B <?= htmlspecialchars($before['bronze_team'] ?? '—') ?></small><?php endif; ?><small>After: G <?= htmlspecialchars($after['gold_team'] ?? '—') ?> · S <?= htmlspecialchars($after['silver_team'] ?? '—') ?> · B <?= htmlspecialchars($after['bronze_team'] ?? '—') ?></small></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php page_foot(); ?>
